import{_ as t,o as i,c as e,a2 as a}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"分阶段产品路线图","description":"Hearth Stage 0–6 产品路线图：阶段目标、范围、退出条件、学习目标与明确推迟项。","frontmatter":{"title":"分阶段产品路线图","description":"Hearth Stage 0–6 产品路线图：阶段目标、范围、退出条件、学习目标与明确推迟项。","outline":[2,3]},"headers":[],"relativePath":"delivery/roadmap.md","filePath":"delivery/roadmap.md","lastUpdated":null}'),r={name:"delivery/roadmap.md"};function o(d,l,n,s,p,u){return i(),e("div",null,[...l[0]||(l[0]=[a('<p class="eyebrow">PRODUCT ROADMAP</p><h1 id="分阶段产品路线图" tabindex="-1">分阶段产品路线图 <a class="header-anchor" href="#分阶段产品路线图" aria-label="Permalink to &quot;分阶段产品路线图&quot;">​</a></h1><p class="lead">Stage 0–6 的能力门槛：每个阶段交付什么、何时算完成、什么条件不满足就不能进入下一阶段。</p><h2 id="本篇怎么读" tabindex="-1">本篇怎么读 <a class="header-anchor" href="#本篇怎么读" aria-label="Permalink to &quot;本篇怎么读&quot;">​</a></h2><ul><li>Stage 是能力层级，不是日期或工期。</li><li>MVP 位于 Stage 1 的早期出口，不是 Stage 6 的产物。</li><li>每个阶段都必须同时有用户可见界面、持久状态、验证证据和恢复路径。</li><li>阶段退出条件全部满足才算完成；可以停留、试用和回退，但不能跳步。</li></ul><hr><h2 id="分阶段产品路线图-从原型到-personal-agent-os" tabindex="-1">分阶段产品路线图：从原型到 Personal Agent OS <a class="header-anchor" href="#分阶段产品路线图-从原型到-personal-agent-os" aria-label="Permalink to &quot;分阶段产品路线图：从原型到 Personal Agent OS&quot;">​</a></h2><h3 id="推进原则" tabindex="-1">推进原则 <a class="header-anchor" href="#推进原则" aria-label="Permalink to &quot;推进原则&quot;">​</a></h3><ul><li>以能力门槛推进，不以日历承诺推进；</li><li>每个阶段都能独立交付价值；</li><li>Stage 1 内部必须尽早出现可每天使用的 MVP，而不是等 Stage 6 才形成产品；</li><li>每个阶段都必须同时交付用户可见界面、持久状态、验证证据和恢复路径；</li><li>前端与后端按纵向切片同步推进，不允许“先做完后端再补界面”；</li><li>先证明可靠，再扩大覆盖；</li><li>Codex 是第一个外部执行器，但不是唯一能力来源；</li><li>不在早期自研通用 Sandbox、模型推理引擎或完整 Agent 框架；</li><li>每个阶段都同时有产品门槛和学习门槛；</li><li>任何自动化能力进入真实副作用前，必须先通过安全与恢复测试。</li></ul><h3 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>用户拿到的产品形态</th><th>核心能力</th><th>仍明确不做</th><th>主要风险</th></tr></thead><tbody><tr><td>Stage 0</td><td>可点击的端到端产品原型</td><td>产品楔子、任务集、协议、交互、评测和安全基线</td><td>真实执行、真实副作用</td><td>目标漂移、原型与实现脱节</td></tr><tr><td>Stage 1</td><td>本地可用的个人任务工作台；早期出现 MVP</td><td>可恢复内核、Codex、Web 任务卡、审批、产物、恢复</td><td>真实邮箱自动发送、GUI、主动循环、多设备</td><td>状态恢复、重复副作用、集成不稳</td></tr><tr><td>Stage 2</td><td>能处理日常内容工作的 Personal Operator</td><td>邮件/日历/文档/网页/数据真实任务，Context Compiler，Memory v0</td><td>桌面 GUI、完整主动性、自进化</td><td>权限、平台限制、上下文成本</td></tr><tr><td>Stage 3</td><td>能操作桌面的 Computer Operator</td><td>agentd、GUI、接管、桌面隔离与高风险审批</td><td>多设备长期同步、无评估进化</td><td>脆弱性、验证、不可逆操作</td></tr><tr><td>Stage 4</td><td>低打扰的 Proactive Personal Agent</td><td>Trigger、主动循环、注意力预算、手机 PWA、设备配对</td><td>完整多设备执行、技能自动晋升</td><td>通知疲劳、越权、移动安全</td></tr><tr><td>Stage 5</td><td>会积累个人上下文并安全改进方法的 Agent</td><td>Memory OS、Evolution OS、技能评估/晋升/回滚</td><td>企业多租户、公开市场</td><td>记忆污染、技能漂移、评估偏差</td></tr><tr><td>Stage 6</td><td>多设备、可迁移、可长期运行的 Personal Agent OS v1.0</td><td>同步、离线队列、设备撤销、备份迁移、长期运维</td><td>无边界的无人值守高风险自动化</td><td>同步冲突、设备安全、运维</td></tr></tbody></table><p>阶段之间不是按日期切换的瀑布，而是能力依赖关系。每个阶段都可以停留、试用和回退；产品在任一阶段都应保持当前范围内的完整可用性。</p><p><strong>MVP 的位置：</strong> MVP 是 Stage 1 的早期产品出口，位于完整 Stage 1 门槛之前。它不包含邮件、日历、GUI、主动性、完整记忆和多设备，但必须包含真实执行、持久任务状态、Web 任务卡、产物、审批演练和失败恢复。具体定义见 25.3。</p><h3 id="stage-0-定义、原型与基线" tabindex="-1">Stage 0：定义、原型与基线 <a class="header-anchor" href="#stage-0-定义、原型与基线" aria-label="Permalink to &quot;Stage 0：定义、原型与基线&quot;">​</a></h3><p><strong>目标：</strong> 在进入真实实现前，把产品、交互、协议和验收钉住。Stage 0 不是纯文档阶段，必须产出一个可点击的端到端产品原型。</p><p>交付：</p><ul><li>一页产品定义与非目标；</li><li>首选用户和 20–30 个真实任务清单；</li><li>八类任务覆盖矩阵；</li><li>第一个产品楔子：优先选择一个高频、低外部风险的任务族做 MVP；</li><li>可点击的 Web 原型：今日、任务卡、新任务、需要你、产物、失败/恢复和审批状态；</li><li>每个 UI 状态对应的投影字段和主动作；</li><li>Event、Task、Run、Executor、Approval、Receipt 的 schema v0；</li><li>威胁模型和风险分级；</li><li>评测任务集与验证器 v0；</li><li>Build vs Integrate ADR；</li><li>仓库、CI、编码规范和版本策略。</li></ul><p>退出条件：</p><ul><li>能用一句话说明 Hearth 不是什么；</li><li>每个核心实体有不变量；</li><li>至少 12 个任务有可执行验收；</li><li>高风险动作有明确审批路径；</li><li>用户可以在原型中连续完成“创建任务 → 看到状态 → 审批 → 查看产物 → 查看恢复路径”；</li><li>原型中的每个状态都能映射到真实数据契约，而不是只能演示的动画；</li><li>已决定 Stage 1 不自研 Sandbox 内核。</li></ul><h3 id="stage-1-durable-personal-kernel-与-mvp" tabindex="-1">Stage 1：Durable Personal Kernel 与 MVP <a class="header-anchor" href="#stage-1-durable-personal-kernel-与-mvp" aria-label="Permalink to &quot;Stage 1：Durable Personal Kernel 与 MVP&quot;">​</a></h3><p><strong>目标：</strong> 证明一个个人 Agent 可以本地常驻、可中断、可恢复、可审批、可审计地完成真实任务，并尽早形成一个每天可用的最小产品。</p><p><strong>MVP 完成线：</strong> Stage 1 不等待所有内核细节完成后才展示产品。先在一个窄任务族上完成真实纵向切片，达到 25.3 的 MVP 门槛；随后继续补齐副作用安全、第二任务族和故障注入，完成整个 Stage 1。</p><p>范围：</p><ul><li><code>hearthd</code> 单进程常驻服务；</li><li>SQLite WAL Event Log、投影和 migration；</li><li>Task / Ticket / Run / Assignment / Lease；</li><li>outbox、幂等键、Receipt；</li><li>Codex Executor：代码、测试、Issue/PR、调研、文档和多文件工作区；</li><li>workspace 生命周期、只读证据、文件 diff；</li><li>Policy、Mandate、Approval v0；</li><li>Web 作为主入口：任务创建、任务卡、详情/时间线、审批、产物、失败与恢复；</li><li>CLI 作为自动化和诊断入口，不替代产品界面；手机 PWA 留到 Stage 4；</li><li>Artifact 和验证器 v0；</li><li>基础 Token 记录与预算；</li><li>崩溃恢复和故障注入测试。</li></ul><p>首批真实任务：</p><ol><li>从 Issue 到代码修改、测试和 PR 草稿；</li><li>三份资料来源整理成对比表和报告；</li><li>读取一组文档，生成周报草稿和引用清单；</li><li>文件整理与可复现转换；</li><li>需要审批的外部副作用（使用测试 Effect 或本地测试服务）。</li></ol><p>退出条件：</p><ul><li>MVP 已能在浏览器中每天使用一个窄任务族；</li><li><code>kill -9</code> 后能恢复到可继续状态；</li><li>200 次故障注入下重复外部副作用为 0；</li><li>Codex 任务有结构化产物和验证；</li><li>没有任务仅凭自然语言“完成”；</li><li>任务卡能清楚显示状态、产物和下一步；</li><li>创建、取消、重试、审批、查看产物和恢复都能通过 Web 完成；</li><li>至少 10 个真实任务通过人工验收；</li><li>Token 和人工分钟有基线。</li></ul><p>学习门槛：</p><ul><li>理解事件日志、单写者、lease、fencing token 和恢复；</li><li>理解 Codex 的能力边界和工作区隔离；</li><li>理解审批、outbox 和 Receipt 的区别；</li><li>形成第一份失败分类和路由数据。</li></ul><h3 id="stage-2-personal-operator" tabindex="-1">Stage 2：Personal Operator <a class="header-anchor" href="#stage-2-personal-operator" aria-label="Permalink to &quot;Stage 2：Personal Operator&quot;">​</a></h3><p><strong>目标：</strong> 从“会做文件任务”扩展到“能做大多数日常数字内容工作”。</p><p>范围：</p><ul><li>Email Connector：只读同步、线程、联系人、附件、草稿、待审批发送；</li><li>Calendar Connector：只读、冲突检查、待审批写入；</li><li>Docs/Drive Connector：读取、版本、导出、待审批分享；</li><li>Browser Executor：研究、下载、无 API 表单；</li><li>Document/Data Executor：PDF、Office、表格、OCR、转换、对账；</li><li>Context Compiler 和 Token Governor v1；</li><li>Memory v0：Episodic + Semantic，带来源、预算和基本遗忘；</li><li>任务模板和第一批可复用流程；</li><li>更完整的通知与产物中心。</li></ul><p>退出条件：</p><ul><li>邮件“读—理解—起草—审批—发送—回执”闭环可用；</li><li>日历冲突检查与待审批写入可用；</li><li>文档转换结果可验证；</li><li>网页研究有来源和引用；</li><li>常见任务的人工分钟显著下降；</li><li>没有跨账户、跨项目数据串扰；</li><li>失败时能恢复或明确转人工。</li></ul><h3 id="stage-3-computer-operator" tabindex="-1">Stage 3：Computer Operator <a class="header-anchor" href="#stage-3-computer-operator" aria-label="Permalink to &quot;Stage 3：Computer Operator&quot;">​</a></h3><p><strong>目标：</strong> 覆盖没有 API 的桌面软件和跨应用流程。</p><p>范围：</p><ul><li>设备 agentd 与桌面能力注册；</li><li>GUI Executor：可访问性树、截图、键鼠、文件选择；</li><li>隔离虚拟桌面；</li><li>浏览器/桌面实时接管；</li><li>高风险桌面动作审批；</li><li>桌面任务验证与恢复；</li><li>应用白名单、窗口范围和系统安全边界。</li></ul><p>退出条件：</p><ul><li>至少 5 个真实桌面任务可以完成并验证；</li><li>接管流程可用，用户能暂停、操作和交还；</li><li>GUI 失败不会留下半完成的高风险状态；</li><li>桌面操作没有读取密码库或越权系统设置；</li><li>Token 和人工分钟在可接受范围。</li></ul><h3 id="stage-4-proactive-personal-agent" tabindex="-1">Stage 4：Proactive Personal Agent <a class="header-anchor" href="#stage-4-proactive-personal-agent" aria-label="Permalink to &quot;Stage 4：Proactive Personal Agent&quot;">​</a></h3><p><strong>目标：</strong> 让 Hearth 在有限授权内主动工作，同时保持低打扰。</p><p>范围：</p><ul><li>邮件、日历、文件、网页和任务依赖 Trigger；</li><li>主动循环和后台批处理；</li><li>注意力预算、静默时段、聚合通知；</li><li>手机 PWA：查看、审批、接管、发起、通知；</li><li>设备配对、安全隧道、推送脱敏；</li><li>A1/A2 自主级别；</li><li>任务卡和“需要你”收件箱成熟；</li><li>主动模式的开关和对照评估。</li></ul><p>退出条件：</p><ul><li>主动任务真实有用，不制造通知疲劳；</li><li>每任务打断次数 ≤ 1；</li><li>高风险动作仍需审批；</li><li>手机可完成关键审批和接管；</li><li>用户能随时暂停、撤销和降级主动模式；</li><li>无后台无限循环和预算透支。</li></ul><h3 id="stage-5-memory-os-与-evolution-os" tabindex="-1">Stage 5：Memory OS 与 Evolution OS <a class="header-anchor" href="#stage-5-memory-os-与-evolution-os" aria-label="Permalink to &quot;Stage 5：Memory OS 与 Evolution OS&quot;">​</a></h3><p><strong>目标：</strong> 让系统真正积累个人上下文，并能安全地改进方法。</p><p>范围：</p><ul><li>五类记忆完整落地；</li><li>记忆写入、冲突、检索、预算、遗忘、同步；</li><li>记忆浏览器和“为什么召回”视图；</li><li>轨迹挖掘、技能候选、版本和评估集；</li><li>Shadow → Canary → Promote → Rollback；</li><li>技能权限约束；</li><li>核心 Runtime 人工 PR 修改；</li><li>至少一个完整技能晋升案例。</li></ul><p>退出条件：</p><ul><li>记忆可纠正、可遗忘、可导出；</li><li>记忆注入准确率达标；</li><li>技能晋升有对照评估；</li><li>没有权限扩大或安全回归；</li><li>回滚可用；</li><li>用户能理解系统为什么这样做。</li></ul><h3 id="stage-6-personal-agent-os" tabindex="-1">Stage 6：Personal Agent OS <a class="header-anchor" href="#stage-6-personal-agent-os" aria-label="Permalink to &quot;Stage 6：Personal Agent OS&quot;">​</a></h3><p><strong>目标：</strong> 多设备、长期驻留、可迁移、可自托管。</p><p>范围：</p><ul><li>多设备 agentd；</li><li>事件同步、cursor、lease、fencing；</li><li>设备能力路由和离线队列；</li><li>设备丢失撤销；</li><li>远程执行和加密传输；</li><li>备份、恢复、迁移和升级；</li><li>长期运行监控；</li><li>资源调度和配额；</li><li>可选远程 Sandbox。</li></ul><p>退出条件：</p><ul><li>一个逻辑 Agent、多个设备一致；</li><li>设备切换不丢任务、不重复副作用；</li><li>离线恢复率达标；</li><li>迁移后事件、记忆和技能可验证；</li><li>设备撤销立即可靠；</li><li>长期运行无内存泄漏和状态漂移。</li></ul><h3 id="学习目标映射" tabindex="-1">学习目标映射 <a class="header-anchor" href="#学习目标映射" aria-label="Permalink to &quot;学习目标映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>学习目标</th><th>主要落点</th><th>阶段</th><th>可验证交付</th></tr></thead><tbody><tr><td>Maka / Pi 的 Runtime</td><td>Native Runtime、session tree、steering、compaction</td><td>1–2</td><td>可重放 session 和上下文压缩测试</td></tr><tr><td>DeerFlow 的完整 Harness</td><td>Ticket/Run、状态机、middleware、恢复</td><td>1</td><td>Run 生命周期和故障注入</td></tr><tr><td>OpenSandbox / OpenBot 隔离</td><td>Execution Gateway、Sandbox Provider、takeover、receipt</td><td>1–3</td><td>攻击矩阵和接管演示</td></tr><tr><td>OpenClaw 的自主控制</td><td>Gateway、channels、devices、attention、autonomy</td><td>2–4</td><td>Source→Trigger→Run→Receipt 闭环</td></tr><tr><td>Hermes 的记忆与进化</td><td>记忆预算、约束、技能生命周期、评估</td><td>5</td><td>记忆评估和技能晋升/回滚案例</td></tr><tr><td>OpenMuse / OpenDots 的自主性</td><td>durable job、checkpoint、低打扰任务卡</td><td>1–4</td><td>崩溃恢复和手机任务卡演示</td></tr><tr><td>Codex Executor</td><td>长链路、多文件、研究、文档、代码</td><td>1</td><td>任务包、结构化输出和验收报告</td></tr></tbody></table><h3 id="明确推迟" tabindex="-1">明确推迟 <a class="header-anchor" href="#明确推迟" aria-label="Permalink to &quot;明确推迟&quot;">​</a></h3><p>Stage 0–1 的 MVP 不做：</p><ul><li>自研容器/虚拟机/内核；</li><li>自研基础模型或推理引擎；</li><li>自建公开 Agent 市场；</li><li>企业 IAM、多租户、计费；</li><li>完整桌面 Office 替代品；</li><li>无边界的自动付款、签约和公开发布；</li><li>一开始接入所有渠道；</li><li>无评估的自进化；</li><li>多设备复杂同步；</li><li>原生 iOS/Android 应用；</li><li>只有 CLI 或 API、没有浏览器产品路径的“伪 MVP”；</li><li>为了赶底层进度而把前端整体推迟到后续阶段。</li></ul>',65)])])}const c=t(r,[["render",o]]);export{h as __pageData,c as default};
